ry, size_values_str, xs_sales, s_sales, m_sales, l_sales, xl_sales, xxl_sales, IFF( LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ) IS NULL, \'1:1:1:1:1:1\', CONCAT( ROUND( xs_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( s_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( m_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( l_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( xl_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( xxl_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ) ) ) AS sale_ratio from main where size_values_str = \'XS, S, M, L, XL, XXL\' union all select category, size_values_str, xs_sales, s_sales, m_sales, l_sales, xl_sales, xxl_sales, IFF( LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ) IS NULL, \'1:1:1:1:1\', CONCAT( ROUND( s_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( m_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( l_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( xl_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ),\':\', ROUND( xxl_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ), 1 ) ) ) AS sale_ratio from main where size_values_str = \'S, M, L, XL, XXL\' union all select category, size_values_str, xs_sales, s_sales, m_sales, l_sales, xl_sales, xxl_sales, IFF( LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0), NULLIF(xxl_sales, 0) ) IS NULL, \'1:1:1:1\', CONCAT( ROUND( s_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( m_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( l_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( xl_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( xxl_sales / LEAST( NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ) ) ) AS sale_ratio from main where size_values_str = \'S, M, L, XL\' union all select category, size_values_str, xs_sales, s_sales, m_sales, l_sales, xl_sales, xxl_sales, IFF( LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ) IS NULL, \'1:1:1:1:1\', CONCAT( ROUND( xs_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( s_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( m_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( l_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ),\':\', ROUND( xl_sales / LEAST( NULLIF(xs_sales, 0), NULLIF(s_sales, 0), NULLIF(m_sales, 0), NULLIF(l_sales, 0), NULLIF(xl_sales, 0) ), 1 ) ) ) AS sale_ratio from main where size_values_str = \'XS, S, M, L, XL\' ) select a.*, b.sale_ratio from snitch_db.maplemonk.current_size_split_all_sku a left join sales_ratio b on a.category = b.category and a.size_values_str = b.size_values_str ; create or replace table snitch_db.maplemonk.current_size_sales_split_all_sku_order_Split as ( WITH src AS ( SELECT sku_group, size_ratio, sale_ratio, 1500::NUMBER AS reorder_qty FROM current_size_sales_split_all_sku ), arr AS ( SELECT sku_group, SPLIT(size_ratio, \':\') AS inv_arr, SPLIT(sale_ratio, \':\') AS sale_arr, reorder_qty FROM src ), inv_flat AS ( SELECT a.sku_group, f.index::NUMBER AS idx, COALESCE(TRY_TO_DOUBLE(TO_VARCHAR(f.value)), 0.0) AS inv FROM arr a, LATERAL FLATTEN(input => a.inv_arr) f ), sale_flat AS ( SELECT a.sku_group, f.index::NUMBER AS idx, COALESCE(TRY_TO_DOUBLE(TO_VARCHAR(f.value)), 0.0) AS sale FROM arr a, LATERAL FLATTEN(input => a.sale_arr) f ), exploded AS ( SELECT COALESCE(i.sku_group, s.sku_group) AS sku_group, COALESCE(i.idx, s.idx) AS idx, COALESCE(i.idx, s.idx) + 1 AS pos, COALESCE(i.inv, 0.0) AS inv, COALESCE(s.sale, 0.0) AS sale FROM inv_flat i FULL OUTER JOIN sale_flat s ON i.sku_group = s.sku_group AND i.idx = s.idx ), breakpoints AS ( SELECT e.sku_group, a.reorder_qty, e.pos, e.inv, e.sale, IFF(e.sale > 0, e.inv / e.sale, 1e18) AS b FROM exploded e JOIN arr a ON e.sku_group = a.sku_group ), ordered AS ( SELECT *, SUM(IFF(sale > 0, inv, 0.0)) OVER (PARTITION BY sku_group ORDER BY b, pos) AS cum_inv, SUM(IFF(sale > 0, sale, 0.0)) OVER (PARTITION BY sku_group ORDER BY b, pos) AS cum_sale, LEAD(b) OVER (PARTITION BY sku_group ORDER BY b, pos) AS next_b FROM breakpoints ), k_choice AS ( SELECT sku_group, reorder_qty, (reorder_qty + cum_inv) / NULLIF(cum_sale, 0.0) AS k FROM ordered QUALIFY k >= b AND (next_b IS NULL OR k <= next_b) ), order_raw AS ( SELECT e.sku_group, e.pos, e.inv, e.sale, c.reorder_qty, c.k, GREATEST(c.k * e.sale - e.inv, 0.0) AS order_amt FROM breakpoints e JOIN k_choice c ON e.sku_group = c.sku_group ), rounding AS ( SELECT *, FLOOR(order_amt) AS order_floor, (order_amt - FLOOR(order_amt)) AS frac, SUM(FLOOR(order_amt)) OVER (PARTITION BY sku_group) AS sum_floor FROM order_raw ), final_alloc AS ( SELECT *, (reorder_qty - sum_floor)::NUMBER AS remainder, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY frac DESC, pos) AS rn FROM rounding ), final AS ( SELECT sku_group, pos, inv, (order_floor + IFF(rn <= remainder, 1, 0))::NUMBER AS order_qty FROM final_alloc ), final_result AS ( SELECT sku_group, LISTAGG(order_qty::STRING, \':\') WITHIN GROUP (ORDER BY pos) AS order_qty_str FROM final GROUP BY sku_group ), ratio_flat AS ( SELECT f.sku_group, fl.index AS pos, TRY_TO_DOUBLE(TO_VARCHAR(fl.value)) AS qty FROM final_result f, LATERAL FLATTEN(input => SPLIT(f.order_qty_str, \':\')) fl ), min_vals AS ( SELECT sku_group, MIN(qty) AS min_qty FROM ratio_flat WHERE qty > 0 GROUP BY sku_group ), ratio_calc AS ( SELECT r.sku_group, r.pos, ROUND(r.qty / m.min_qty, 1) AS ratio_val FROM ratio_flat r JOIN min_vals m ON r.sku_group = m.sku_group ), final_order_Split as ( SELECT sku_group, LISTAGG(ratio_val::STRING, \':\') WITHIN GROUP (ORDER BY pos) AS order_ratio FROM ratio_calc GROUP BY sku_group ORDER BY sku_group ) select a.sku_group, a.category, a.size_ratio, a.sale_ratio, a.size_values_str, b.order_ratio from snitch_db.maplemonk.current_size_sales_split_all_sku a left join final_order_Split b on a.sku_group = b.sku_group ) ;",
                    "transaction": true
                }
            ) }}
